class Solution {
public:
    std::string addBinary(std::string a, std::string b) {
        std::string ans = "";
        int ft = a.length() - 1;
        int sd = b.length() - 1;
        int carry = 0;

        // Keep looping if there are digits left in a, or b, or if there is a leftover carry
        while (ft >= 0 || sd >= 0 || carry > 0) {
            int sum = carry;

            // Add digit from string 'a' if available
            if (ft >= 0) {
                sum += a[ft] - '0'; // Convert character '0'/'1' to integer 0/1
                ft--;
            }

            // Add digit from string 'b' if available
            if (sd >= 0) {
                sum += b[sd] - '0'; // Convert character '0'/'1' to integer 0/1
                sd--;
            }

            // The value to push is sum % 2 (either 0 or 1)
            ans.push_back((sum % 2) + '0'); 

            // The new carry is sum / 2 (1 if sum was 2 or 3, else 0)
            carry = sum / 2; 
        }

        // Reverse in-place and return
        std::reverse(ans.begin(), ans.end());
        return ans;
    }
};
